def transform(grid):
    if not grid:
        return grid

    h, w = len(grid), len(grid[0])

    # Output width is exactly half
    output_w = w // 2

    # Find background (most frequent color)
    from collections import Counter
    counts = Counter()
    for row in grid:
        for val in row:
            counts[val] += 1
    bg = max(counts, key=counts.get)

    # Build output with background
    output = [[bg] * output_w for _ in range(h)]

    for r in range(h):
        # Check if 8 (azure) exists in left half
        has_8_left = any(grid[r][c] == 8 for c in range(output_w))

        # Process left half into output
        for c in range(output_w):
            val = grid[r][c]
            if val == bg:
                continue
            if val == 8 and not has_8_left:
                # If this is the first 8, set flag, don't copy
                pass
            elif val == 8:
                output[r][c] = 8
            elif val == 0:  # 0 is transparent
                continue
            else:
                output[r][c] = val

        # If no 8 in left half, also process right half
        if not has_8_left:
            for c in range(output_w):
                right_c = w - 1 - c
                val = grid[r][right_c]
                if val == bg or val == 0:
                    continue
                # Map to output position from right
                out_c = output_w - 1 - c
                if val == 4:
                    output[r][out_c] = 4
                elif val == 7:
                    output[r][out_c] = 7

    return output
